//! The Metal shell, OCIO's `MetalShaderClassWrapper`: the resources and `ocio_transform` (the op
//! bodies of `gpu/ops.rs`, written once for every language, ROADMAP G6) are members of a struct
//! the fragment entry point builds. Nothing here is colour maths.

use super::*;
use crate::gpu_shader_utils::ShaderText;

impl GpuProcessor {
    // =========================================================================
    // Metal Shading Language Generation
    // =========================================================================

    /// Generates Metal shader code.
    ///
    /// As OCIO's `MetalShaderClassWrapper`: the OCIO resources (the uniform buffer, the LUT
    /// textures and their samplers) are members of a struct whose member functions are the
    /// helpers and `ocio_transform`, so they can reach the resources (Metal has no global
    /// resources, and resource attributes belong on entry-point arguments only). The fragment
    /// entry point takes the resources, builds the struct and calls `ocio_transform`.
    pub(super) fn generate_metal(
        &self,
        code: &mut String,
        uniform_bindings: &[Option<OpUniforms>],
        uniforms: &[GpuUniform],
    ) {
        let mut st = ShaderText::new();
        let d = &dialect::METAL;

        st.line("// Metal Shading Language Generated by vfx-ocio");
        st.line("#include <metal_stdlib>");
        st.line("using namespace metal;");
        st.new_line();

        // Uniform struct
        self.emit_uniform_decls_metal(&mut st, uniforms);

        // Vertex output / fragment input structure
        st.line("struct VertexOut {");
        st.indent();
        st.line("float4 position [[position]];");
        st.line("float2 texCoord [[user(locn0)]];");
        st.dedent();
        st.line("};");
        st.new_line();

        let tex_type = |t: GpuTextureType| match t {
            GpuTextureType::Texture1D => "texture1d<float>",
            GpuTextureType::Texture2D => "texture2d<float>",
            GpuTextureType::Texture3D => "texture3d<float>",
        };

        // The resources and the functions that use them.
        st.line("struct OcioShader {");
        st.indent();
        if !uniforms.is_empty() {
            st.line("OcioUniforms uniforms;");
        }
        for tex in &self.textures {
            st.linef(format!("{} {};", tex_type(tex.texture_type), tex.name));
            st.linef(format!("sampler {}_sampler;", tex.name));
        }
        st.new_line();
        for line in ops::helpers(self, d, uniform_bindings) {
            st.linef(line);
        }
        st.line("float4 ocio_transform(float4 color) {");
        st.indent();
        for line in ops::body(self, d, uniform_bindings) {
            st.linef(line);
        }
        st.line("return color;");
        st.dedent();
        st.line("}");
        st.dedent();
        st.line("};");
        st.new_line();

        // Fragment entry point
        st.line("fragment float4 fragmentMain(VertexOut in [[stage_in]],");
        st.indent();
        st.line("texture2d<float> inputTexture [[texture(0)]],");
        st.line("sampler inputSampler [[sampler(0)]]");
        let mut members: Vec<String> = Vec::new();
        if !uniforms.is_empty() {
            st.line(", constant OcioUniforms& uniforms [[buffer(0)]]");
            members.push("uniforms".into());
        }
        for (idx, tex) in self.textures.iter().enumerate() {
            st.linef(format!(
                ", {} {} [[texture({})]]",
                tex_type(tex.texture_type),
                tex.name,
                idx + 1
            ));
            st.linef(format!(
                ", sampler {}_sampler [[sampler({})]]",
                tex.name,
                idx + 1
            ));
            members.push(tex.name.clone());
            members.push(format!("{}_sampler", tex.name));
        }
        st.dedent();
        st.line(") {");
        st.indent();
        st.linef(format!("OcioShader ocio = {{ {} }};", members.join(", ")));
        st.line("return ocio.ocio_transform(inputTexture.sample(inputSampler, in.texCoord));");
        st.dedent();
        st.line("}");

        code.push_str(st.code());
    }
}
